Hier ist eine C++-Funktion, die einen Markdown-String in einen HTML-String konvertiert:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>
#include "boost/algorithm/string.hpp"

// Function to convert Markdown to HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream htmlStream;
    htmlStream << "<div class='markdown'>";

    // Split the input string into lines
    std::vector<std::string> lines;
    boost::algorithm::split(lines, markdown, boost::is_any_of("\n"));

    // Iterate through each line
    for (const auto& line : lines) {
        // Remove leading/trailing whitespace
        boost::algorithm::trim(line);

        // Handle different Markdown elements
        if (boost::starts_with(line, "# ")) {
            // Heading
            const std::string level = line.substr(0, line.find(" "));
            htmlStream << "<h" << level.size() << ">" << boost::algorithm::trim_copy_copy(line.substr(line.find(" ") + 1)) << "</h" << level.size() << ">\n";
        } else if (boost::starts_with(line, "## ")) {
            // Subheading
            const std::string level = line.substr(0, line.find(" "));
            htmlStream << "<h" << level.size() + 1 << ">" << boost::algorithm::trim_copy_copy(line.substr(line.find(" ") + 1)) << "</h" << level.size() + 1 << ">\n";
        } else if (boost::starts_with(line, "### ")) {
            // Sub-subheading
            const std::string level = line.substr(0, line.find(" "));
            htmlStream << "<h" << level.size() + 2 << ">" << boost::algorithm::trim_copy_copy(line.substr(line.find(" ") + 1)) << "</h" << level.size() + 2 << ">\n";
        } else if (boost::starts_with(line, "* ") || boost::starts_with(line, "- ")) {
            // Bullet point
            htmlStream << "<ul><li>" << boost::algorithm::trim_copy_copy(line.substr(line.find_first_of(" *-") + 1)) << "</li></ul>\n";
        } else if (boost::starts_with(line, "1. ") || boost::starts_with(line, "2. ") || boost::starts_with(line, "3. ") || boost::starts_with(line, "4. ") || boost::starts_with(line, "5. ") || boost::starts_with(line, "6. ") || boost::starts_with(line, "7. ") || boost::starts_with(line, "8. ") || boost::starts_with(line, "9. ") || boost::starts_with(line, "0. ")) {
            // Numbered list
            htmlStream << "<ol><li>" << boost::algorithm::trim_copy_copy(line.substr(line.find_first_of(". ") + 1)) << "</li></ol>\n";
        } else if (boost::starts_with(line, "> ") || boost::starts_with(line, ">> ") || boost::starts_with(line, ">>> ")) {
            // Blockquote
            std::string indent = line.substr(0, line.find_first_of(" \t") + 1);
            std::string content = boost::algorithm::trim_copy_copy(line.substr(indent.size()));
            htmlStream << "<blockquote>\n";
            while (!content.empty() && boost::starts_with(content, indent)) {
                htmlStream << "<p>" << boost::algorithm::trim_copy_copy(content.substr(indent.size())) << "</p>\n";
                content = boost::algorithm::trim_copy_copy(content.substr(indent.size()));
            }
            htmlStream << "</blockquote>\n";
        } else if (boost::starts_with(line, "`") && boost::ends_with(line, "`")) {
            // Inline code
            htmlStream << "<code>" << boost::algorithm::trim_copy_copy(line.substr(1, line.size() - 2)) << "</code>";
        } else if (boost::starts_with(line, "```\n") && boost::ends_with(line, "```\n")) {
            // Code block
            std::string content = boost::algorithm::trim_copy_copy(line.substr(4, line.size() - 8));
            htmlStream << "<pre><code>" << content << "</code></pre>\n";
        } else if (boost::starts_with(line, "[") && boost::ends_with(line, "]")) {
            // Link
            std::string linkText = boost::algorithm::trim_copy_copy(line.substr(1, line.find_last_of(" ") - 1));
            std::string href = boost::algorithm::trim_copy_copy(line.substr(line.find_last_of(" ") + 1, line.size() - 1));
            htmlStream << "<a href='" << href << "'>" << linkText << "</a>";
        } else {
            // Plain text
            htmlStream << "<p>" << line << "</p>\n";
        }
    }

    htmlStream << "</div>";
    return htmlStream.str();
}

int main() {
    std::string markdown = "### Heading\n"
                           "Bullet point: * Item 1\n"
                           "Bullet point: - Item 2\n"
                           "Numbered list:\n"
                           "1. Item 1\n"
                           "2. Item 2\n"
                           "Blockquote:\n"
                           "> This is a blockquote.\n"
                           "Code: `int main() { ... }`\n"
                           "Code block:\n"
                           "```\n"
                           "std::cout << \"Hello, world!\" << std::endl;\n"
                           "```\n"
                           "Link: [Google](https://www.google.com/)";

    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Die Funktion `convertMarkdownToHtml` nimmt einen Markdown-String als Eingabe und gibt den konvertierten HTML-String zurück. Die Funktionslogik basiert auf der Verarbeitung der verschiedenen Markdown-Elemente, wie z.B. Überschriften, Listen, Blockquote, Code, Links, etc. 

In der `main`-Funktion wird ein Beispiel-String für den Test der Funktion angegeben, und der resultierende HTML-String wird ausgegeben. 

Achtung: Die Funktion basiert auf Boost und wird von Boost abhängig sein. Wenn Sie Boost nicht verwenden möchten, können Sie andere Bibliotheken wie z.B. PugiXML oder RapidJSON für die Verarbeitung von Markdown verwenden.

